using Godot;
using TIndustry.Shared;

namespace TIndustry.Godot;

/// <summary>
/// Mindustry-dark home: the pixel logo (generated by tools/art) over Continua / Campagna / Nuova partita / Esci.
/// Shown over Main until the player picks a route; behind it the map scrolls slowly (World.SyncHomeCamera).
/// </summary>
public partial class HomePanel : Control
{
    /// <summary>Logo pixels per sprite pixel (at 100% UI scale).</summary>
    private const int LogoScale = 5;

    private Button? _continuaBtn;
    private Button? _resumeBtn;
    private Label? _hint;
    private Control? _quitConfirm;

    // Opened from a game in progress (Esc, Menu): Riprendi goes back to it, and so does Esc.
    private bool _inGame;

    public event Action? ResumeChosen;
    public event Action? ContinuaChosen;
    public event Action? CampaignChosen;
    public event Action? NewGameChosen;
    public event Action? SavesChosen;
    public event Action? SettingsChosen;
    public event Action? QuitChosen;

    public override void _Ready()
    {
        Name = "HomePanel";
        SetAnchorsAndOffsetsPreset(LayoutPreset.FullRect);
        MouseFilter = MouseFilterEnum.Stop;
        Visible = true;
        BuildUi();
        RefreshContinua();
    }

    /// <summary>
    /// Shows the Home. <paramref name="inGame"/> true: over a game in progress (Riprendi first, Esc resumes); false: the
    /// start Home; null (back from one of its panels): as it was.
    /// </summary>
    public void Open(bool? inGame = null)
    {
        _inGame = inGame ?? _inGame;
        Visible = true;
        RefreshContinua();
    }

    /// <summary>True while the Home is over a game in progress (Riprendi shown).</summary>
    public bool InGame => _inGame;

    /// <summary>True while the "Quit the game?" dialog is up.</summary>
    public bool QuitConfirmOpen => _quitConfirm?.Visible == true;

    public void Close() => Visible = false;

    public bool IsOpen => Visible;

    /// <summary>True while the Continua button is shown (there is a save to continue).</summary>
    public bool ContinuaShown => _continuaBtn?.Visible == true;

    /// <summary>Shows a load error in place of the hint line (until the next refresh).</summary>
    public void ShowError(string message)
    {
        if (_hint is not null)
        {
            _hint.Text = message;
            _hint.ThemeTypeVariation = UiTheme.TestoRosso;
        }
    }

    public void RefreshContinua()
    {
        if (_hint is not null)
        {
            _hint.ThemeTypeVariation = UiTheme.TestoTenue;
        }

        var has = FactorySaveStore.Exists(FactorySaveStore.ContinueSlotId);
        if (_resumeBtn is not null)
        {
            _resumeBtn.Visible = _inGame;
        }

        if (_continuaBtn is not null)
        {
            // No save to continue: no button at all (not a disabled one). In a game Riprendi takes its place: Continua
            // would reload the autosave, a few ticks back.
            _continuaBtn.Visible = has && !_inGame;
        }

        if (_hint is not null)
        {
            _hint.Text = _inGame ? "home.suggerimento.riprendi"
                : has ? "home.suggerimento.continua"
                : "home.suggerimento.nuova";
        }
    }

    /// <summary>Esc resumes the game in progress; on the start Home it asks to quit, and with that dialog open it cancels.</summary>
    public override void _UnhandledInput(InputEvent @event)
    {
        if (!Visible)
        {
            return;
        }

        if (@event is InputEventKey { Pressed: true, Echo: false, Keycode: Key.Escape })
        {
            if (_quitConfirm!.Visible)
            {
                _quitConfirm.Visible = false;
            }
            else if (_inGame)
            {
                ResumeChosen?.Invoke();
            }
            else
            {
                AskQuit();
            }

            GetViewport().SetInputAsHandled();
        }
    }

    private void AskQuit()
    {
        _quitConfirm!.Visible = true;
        ((Control)_quitConfirm.FindChild("EsciConferma", true, false)!).GrabFocus();
    }

    /// <summary>Modal "Quit the game?" over the Home: Esci (the focused button, so Enter) or Annulla (Esc).</summary>
    private void BuildQuitConfirm()
    {
        _quitConfirm = new Control { Name = "ConfermaEsci", Visible = false };
        _quitConfirm.SetAnchorsAndOffsetsPreset(LayoutPreset.FullRect);
        AddChild(_quitConfirm);
        var dim = new ColorRect { Color = UiColors.Oscuramento, MouseFilter = MouseFilterEnum.Stop };
        dim.SetAnchorsAndOffsetsPreset(LayoutPreset.FullRect);
        _quitConfirm.AddChild(dim);
        var centered = new CenterContainer();
        centered.SetAnchorsAndOffsetsPreset(LayoutPreset.FullRect);
        _quitConfirm.AddChild(centered);
        var card = new PanelContainer { ThemeTypeVariation = UiTheme.Scheda, CustomMinimumSize = new Vector2(360, 0) };
        centered.AddChild(card);
        var col = new VBoxContainer { ThemeTypeVariation = UiTheme.ColonnaLarga };
        card.AddChild(col);
        col.AddChild(new Label { Text = "home.esci.titolo", HorizontalAlignment = HorizontalAlignment.Center });
        var row = new HBoxContainer { ThemeTypeVariation = UiTheme.RigaLarga };
        col.AddChild(row);
        var cancel = MakeMenuButton("comune.annulla", () => _quitConfirm.Visible = false, "Annulla");
        cancel.SizeFlagsHorizontal = SizeFlags.ExpandFill;
        row.AddChild(cancel);
        var quit = MakeMenuButton("home.esci", () => QuitChosen?.Invoke(), "EsciConferma");
        quit.ThemeTypeVariation = UiTheme.PulsantePrimario;
        quit.SizeFlagsHorizontal = SizeFlags.ExpandFill;
        row.AddChild(quit);
    }

    private void BuildUi()
    {
        var dim = new ColorRect
        {
            Color = UiColors.Oscuramento,
            MouseFilter = MouseFilterEnum.Stop
        };
        dim.SetAnchorsAndOffsetsPreset(LayoutPreset.FullRect);
        AddChild(dim);

        // As tall as its buttons (no blank band without Continua); scrolls only if the scaled window is shorter.
        var card = new PanelContainer { Name = "HomeCard", ThemeTypeVariation = UiTheme.Scheda };
        AddChild(card);
        var scroll = new ScrollContainer();
        card.AddChild(scroll);
        var root = new VBoxContainer { ThemeTypeVariation = UiTheme.ColonnaLarga, SizeFlagsHorizontal = SizeFlags.ExpandFill };
        scroll.AddChild(root);
        CardLayout.CenterToContent(card, scroll, root, 400);

        // The logo at a whole multiple of its pixels, sharp like the blocks.
        var logo = Sprites.For("ui/ui-logo");
        root.AddChild(new TextureRect
        {
            Name = "Logo",
            Texture = logo,
            ExpandMode = TextureRect.ExpandModeEnum.IgnoreSize,
            StretchMode = TextureRect.StretchModeEnum.KeepAspectCentered,
            CustomMinimumSize = logo.GetSize() * LogoScale,
            SizeFlagsHorizontal = SizeFlags.ShrinkCenter,
            TextureFilter = TextureFilterEnum.Nearest,
            MouseFilter = MouseFilterEnum.Ignore
        });

        var sub = new Label
        {
            Text = "home.sottotitolo",
            HorizontalAlignment = HorizontalAlignment.Center,
            ThemeTypeVariation = UiTheme.TestoTenue
        };
        root.AddChild(sub);

        root.AddChild(new Control { CustomMinimumSize = new Vector2(0, 8) });

        _resumeBtn = MakeMenuButton("home.riprendi", () => ResumeChosen?.Invoke());
        _resumeBtn.Name = "Riprendi";
        _resumeBtn.Visible = false;
        root.AddChild(_resumeBtn);
        _continuaBtn = MakeMenuButton("home.continua", () => ContinuaChosen?.Invoke());
        _continuaBtn.Name = "Continua";
        root.AddChild(_continuaBtn);
        root.AddChild(MakeMenuButton("menu.campagna", () => CampaignChosen?.Invoke(), "Campagna"));
        root.AddChild(MakeMenuButton("home.nuova", () => NewGameChosen?.Invoke(), "NuovaPartita"));
        root.AddChild(MakeMenuButton("home.salvataggi", () => SavesChosen?.Invoke(), "Salvataggi"));
        root.AddChild(MakeMenuButton("home.impostazioni", () => SettingsChosen?.Invoke(), "Impostazioni"));
        root.AddChild(MakeMenuButton("home.esci", () => QuitChosen?.Invoke(), "Esci"));

        _hint = new Label
        {
            AutowrapMode = TextServer.AutowrapMode.WordSmart,
            HorizontalAlignment = HorizontalAlignment.Center,
            ThemeTypeVariation = UiTheme.TestoTenue
        };
        root.AddChild(_hint);
        BuildQuitConfirm();
    }

    /// <summary>A Home button; <paramref name="name"/> is its stable node name (what the agents' <c>ui</c> lists).</summary>
    private static Button MakeMenuButton(string label, Action onClick, string? name = null)
    {
        var btn = new Button
        {
            Text = label,
            CustomMinimumSize = new Vector2(0, 36)
        };
        if (name is not null)
        {
            btn.Name = name;
        }

        btn.Pressed += onClick;
        return btn;
    }
}
